update public.disciplines set topics = array['1. Conceitos de Química Geral. Importância da química; misturas e métodos de separação; transformações físicas e químicas; processos endotérmicos/exotérmicos; propriedades físicas; tipos de energia e conversão de energia química.', '2. Modelo atômico. Estrutura eletrônica dos átomos. Organização da Tabela Periódica. Propriedades periódicas. Tipos de fórmulas e modelos. Estrutura de Lewis.', '3. Ligações Químicas. Ligação iônica; energia reticular; energia de hidratação vs. Energia reticular. Ligação covalente; parâmetros de ligação; geometria molecular; modelo VSEPR; teoria da ligação de valência; teoria do orbital molecular; polaridade; forças intermoleculares (interações dipolo-dipolo, forças de van der Waals, ligações de hidrogênio). Estruturas cristalinas de sólidos iônicos e moleculares.', '4. Fórmulas químicas. Mol e massa molar. Determinação de fórmulas empíricas e moleculares.', '5. Funções Inorgânicas. Ácidos; bases; sais; óxidos e nomenclaturas.', '6. Reações químicas. Aspectos energéticos das reações químicas. Principais reações químicas (ácido-base, precipitação, óxido-redução e complexação); balanceamento de reações.', '7. Estequiometria. Cálculos estequiométricos.', '8. Introdução à química de coordenação. Reações de complexação. Ácidos e bases de Lewis. Tipos de ligantes. Estabilidade de complexos e efeito quelato. Ligantes biológicos. Conceito ácido-base de Pearson. Aplicação dos conceitos de química de coordenação em sistemas biológicos, terapêuticos e de diagnóstico clínico envolvendo metais.', 'Conteúdo Prático', '1. Técnicas básicas em laboratório', '2. Propriedades de Substâncias Iônicas e Moleculares', '3. Solubilidade de Sólidos em Líquidos', '4. Preparo de soluções', '5. Reações Químicas', '6. Equilíbrio Ácido-Base', '7. Reatividade de Metais', '8. Síntese de composto de coordenação']::text[]
where id = 1321 and md5(array_to_string(topics, E'\n')) = 'a63277084c1601f97907799b0d4e2d7c';

